 f.change('review-input-v1.2.json',r=>{r.clusters=[{canonicalEventId:'MOCK-SNPS',linkedDiscoveryRecords:[{id:'MOCK-NEWS',relationship:'SAME_NAMED_EVENT',verifiedScope:'MOCK association only',notIndependentOpportunity:true},{id:'MISSING',relationship:'UNRESOLVED'}]}];for(const x of r.reviews){x.fact='MOCK actual versus a different quarter';x.analysis='MOCK not a guidance revision or surprise';x.nextEvidence='MOCK review comparable period';}});
 f.change('derived-review-v1.2/summary.json',r=>{r.parentEventsSha256=hash(fs.readFileSync(join(f.root,scan+'events.json')));r.originalDiscoveryRecords=3;r.inputSha256=hash(fs.readFileSync(join(f.root,'review-input-v1.2.json')));});
