test('body parser preserves row context, decodes entities and provides reproducible source offsets',()=>{
 const source='<html><head><script>BAD</script></head><body><p>Guidance &amp; risk &#x2014; &#160; unchanged</p><table><tr><td>Q3</td><td>1,234</td></tr></table><!-- ignore --><script>BAD</script><p>Next quarter differs.</p></body></html>';
 const r=extractTechOriginal(Buffer.from(source));assert.equal(r.status,'BODY_TEXT_EXTRACTED');assert(!r.blocks.some(b=>/BAD|ignore/.test(b.text)));
 assert(r.blocks.some(b=>b.text==='Q3 1,234'));assert(r.blocks.some(b=>b.text==='Guidance & risk — unchanged'));
 for(const b of r.blocks){assert(b.sourceEnd>b.sourceStart);assert(source.slice(b.sourceStart,b.sourceEnd).length>0);assert.equal(b.index,r.blocks.indexOf(b));}
});
test('unsupported non-HTML source is a local unknown, not a fabricated body',()=>{assert.deepEqual(extractTechOriginal(Buffer.from('{"headline":"MOCK"}')),{status:'UNSUPPORTED_BODY',blocks:[]});});
test('SEC inline hidden metadata is omitted and nested cell divisions stay in one row',()=>{const r=extractTechOriginal(Buffer.from('<html><body><div style="display: none;"><div>HIDDEN</div>SECRET</div><table><tr><td><div>MOCK total</div></td><td><div>1,234</div></td><td>5%</td></tr></table></body></html>'));assert.deepEqual(r.blocks.map(b=>b.text),['MOCK total 1,234 5%']);});
