 const run=()=>new Promise(resolve=>{const c=spawn(process.execPath,['--import','tsx','--input-type=module','-e',code,f.root,join(f.root,'concurrent.json')],{cwd:process.cwd(),windowsHide:true});let out='',err='';c.stdout.on('data',b=>out+=b);c.stderr.on('data',b=>err+=b);c.on('exit',status=>resolve({status,out,err}));});
